INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'building-archival-selves', 'MRG', 'Building Archival Selves', 'In this talk, I will share techniques and lessons learned from my experiences building multiple RAG bots based on personal and institutional archival material.', 'Venkatesh Rao', 'vgururao@gmail.com', 'https://venkateshrao.com', 'General audience essay draft', NULL, 'Nope', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'psychological-safety-i-ii', 'Alumni', 'Psychological Safety I & II', 'Applying lessons from traditional safety literature to questions of AI usage, workplace stress, and professional communication. How can we protocolize the cognitive ergonomics of knowledge work to create better performance and health outcomes at the same time?', 'Timber Stinson-Schroff', 'timber@protocol-institute.org', 'timberschroff.com', 'General audience essay draft', NULL, 'I''d add a note explaining what we expect for the abstract question', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'attention-as-natural-law-certification-as-a-protocol-for-human-perceptual-limits', 'SIGPfB', 'Attention as Natural Law: Certification as a Protocol for Human Perceptual Limits', 'In 1995, Mark Weiser proposed that technology should be designed around the natural structure of human attention: the center, which demands conscious focus, and the periphery, which informs without interrupting. They were describing a constraint, not a preference. Human cognitive architecture has limits that do not negotiate with product roadmaps.

Calm Technology Institute''s certification framework takes that constraint seriously as a protocol design problem. It provides an 81-point framework, organized across six categories -- Attention, Periphery, Durability, Light, Sound, and Materials -- in an attempt to codify human perceptual limits as evaluable criteria, and then build a governed process for determining whether a product complies with them. In Venkatesh Rao''s terms, this is an attempt to treat human attention as New Nature: a regime of reality that certified products must conform to, as reliably as they must conform to the laws of physics.

This talk examines what that attempt looks like in practice. Three problems emerge that any protocol operating in a phenomenological domain must eventually solve.

The first is the formalization problem: how do you write a criterion for something like "works at the periphery of awareness" that a trained evaluator can apply consistently across a physical alarm clock, a digital interface, and a hotel room? The CTI framework''s approach involves operationalizing each principle into observable product behaviors, then distinguishing between criteria that can be verified empirically and those that require calibrated human judgment.

The second is the legitimacy problem. Certification protocols require authority to function. ISO has statutory relationships with national standards bodies. The FDA has enforcement power. CTI has neither. The talk examines the mechanisms through which a small independent body can accumulate protocol legitimacy without institutional scale: published criteria, evaluator training and handbooks, a public certification record, and consortium membership that gives industry partners a stake in the protocol''s integrity.

The third is the maintenance problem. Human perceptual limits are stable, but the technology landscape is not. A protocol written for physical consumer electronics requires revision when it is applied to spatial computing, ambient AI interfaces, or built environments. The talk addresses what it means to maintain a living protocol across rapidly diverging product categories, and what revision processes preserve protocol integrity rather than eroding it.

CTI has now certified products across consumer electronics, productivity tools, and hospitality environments. That record makes it possible to evaluate not only how the framework was designed, but how it has held under real conditions.

A magazine-style companion piece suitable for Protocolized will be available at time of presentation.', 'Amber Case', 'case@calmtech.institute', 'https://www.caseorganic.com/', 'General audience essay draft', NULL, 'Thank you for holding this Symposium! Looking forward to participating!', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'governance-axioms-designing-for-rigidity-and-flux-within-new-natures-protocolize', 'Alumni', 'Governance Axioms: Designing for Rigidity and Flux within New Nature''s Protocolized Systems', 'New Nature aspires to rules that are technologically mediated, precise, and final. Yet because the world is genuinely uncertain, no rule set can be specified against everything that will befall it, and early choices entrench, foreclosing options later designers inherit rather than choose. Durability therefore means engaging five governance axioms: recurring tradeoffs that every collective-decision system must design for rather than assume away. Whatever a protocol formally encodes, the material actors who live under it remain the de facto arbiters of which rules bind and get enforced, so these axioms are worked out in practice, not settled through prior design. Finality trades against emergent discretion, which is why even "immutable" networks layer off-chain governance atop on-chain rigidity. Scale efficiencies trade against the lossiness of compressing behavior into legible rules. Popular control trades against expertise: broad participation legitimizes, yet hard, technical, distributive decisions invite delegation to specialists who must then be checked. Concentrated incentives reliably outmaneuver diffuse ones, so designers must anticipate capture and logrolling. And impartial adjudication of contested tradeoffs demands authority insulated enough to bind, yet accountable enough to trust. These tensions recur from constitutions to consensus algorithms to autonomous agents acting for human principals. Skilled designers navigate them through killswitches, veto-gates, tiered amendment thresholds, and independent arbiters, all mechanisms which more generally hold some system elements steady while enabling others to adapt to change pressures. The accompanying preprint maps the axioms as a design space for the rigidity and flux that sustainable protocol design must countenance.', 'Eric Alston', 'ealston@uwyo.edu', 'x.com/incompleterules', 'Academic preprint (arXiv style)', NULL, 'This sounds like an excellent event!', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'provenance-against-fluency-keeping-an-epistemic-memory-when-the-machine-writes', 'MRG', 'Provenance Against Fluency: Keeping an Epistemic Memory When the Machine Writes', 'When a language model rewrites a sentence, it rarely changes the facts; it changes their epistemic status. "Sources suggest" becomes "evidence indicates"; "declined to comment" becomes "did not respond." Every fact survives; the understanding does not. I call this the smoothness trap: the structural tendency of fluent generated prose to upgrade uncertainty into apparent fact. Its first victims are not novices but trained professionals, whose instinct to read fluency as quality is the one the machine exploits. This talk reframes the problem as one of memory. Working with an LLM is continuous cognitive offloading, and what is lost is not information but provenance — the record of what was evidence, what was inference, what was invented, and what the model smoothed. In a fast workflow there is no original to audit and no moment of return; the system is, in Kei Kreutler''s phrase, designed for threshold forgetting. I will present two protocols, developed across ten cohorts of a methods course for journalists and researchers, that restore an epistemic memory to LLM work: the Two-Register Rule, which holds every text as both reader''s prose and an editor''s ledger tagging each claim by status, and the Audit Trail, a provenance chain from source to published decision. An accompanying essay develops the argument; the talk demonstrates both live on a single passage. This is less a critique of AI than the cognitive ergonomics an AI-native practice requires.', 'Stanislav Lvovsky', 'halfofthesky@gmail.com', 'https://www.pragueschool.media/tutors-llm-lvovsky', 'General audience essay draft', NULL, 'Ертл you for your consideration!', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'political-virtues-for-protocol-societies', 'SIGPSY', 'Political Virtues for Protocol Societies', 'There is an apparently growing array of social movements that are turning to the concept of protocol as a way of reimagining the social order. These include digital rights activists, decolonial struggles, and environmental protection efforts. If protocol-centric visions are to take hold in the world, what kinds of virtues would prepare people for living in those visions? This paper is an attempt to lay groundwork for future discussions of political virtues for protocol societies, in light of emergent discourse among social movements. It first reviews foregoing mappings of political virtues to political orders, contextualizing what follows in earlier scholarship and political practice. It then surveys the manifestations of contemporary movements for a protocol society. This establishes the salience and political significance of protocol as the basis of political imaginaries. Through a thematic analysis of protocol movements'' self-expressions, it identifies a preliminary catalog of virtues that advocates deem appropriate for living well in a protocol society, along with analysis of their relative significance. The paper then concludes with a reflection on those virtues in light of the pedagogies appropriate for inculcating them.', 'Nathan Schneider', 'n@nathanschneider.info', 'https://nathanschneider.info', 'Academic preprint (arXiv style)', NULL, 'Looming forward', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'the-role-of-identity-in-decentralized-dispute-resolution-protocols', 'SIGFPT', 'The Role of Identity in Decentralized Dispute Resolution Protocols', 'In this talk, we will look at how the availability of identity tools shapes what kind of protocols can be robustly built, particularly in the context of decentralized dispute resolution protocols such as Kleros. Particularly, we will look at various ways that an absence of identity information in such protocols requires them to have a financialized character in order to be secure against attacks. We then contrast such identity-agnostic protocols with those that take advantage of a wider range of protocol design choices that are enabled by more recent innovations in decentralized identity such as Proof-of-Personhood protocols and Soulbound Tokens. Drawing from the experience of the transition from v1 to v2 of the Kleros protocol, we see that financialized and identity components can be complementary. Indeed, even notions of identity that are not perfectly robust to attack when used alone can be complemented by financialized aspects to achieve acceptable attack resistance while also enabling a social layer that adds to the legitimacy of decentralized dispute resolution protocols.', 'William George', 'william@kleros.io', 'https://medium.com/kleros/an-interview-with-the-mathematician-kleros-cryptoeconomics-researcher-william-george-969ad417d942', 'Only talk, no artifact planned', NULL, 'N/A', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'a-common-protocol-for-composable-modular-organizations', 'SIGPfB', 'A Common Protocol for Composable, Modular Organizations', 'This talk presents a protocol for making organisations composable: an explicit, shared, machine-readable substrate that replaces the implicit protocols, the hierarchy, meetings, and informal translation work, by which most organisations still coordinate. The argument is simple. External volatility and the arrival of AI agents are two pressures on one weakness: implicit structure. The missing layer is a common protocol that says what an organisation is made of and on what terms its parts combine. The accompanying artefact is O2A, the Open Organisation Alliance: an open standard we have been developing at Boundaryless, set out alongside our forthcoming whitepaper, (provisional: "The Composable Organisation"  June 2026). 

The protocol has two halves. A common alphabet types the organisation as units, offerings, and the relationships among them; a compact contract grammar then governs how units coordinate economically, through three primitives (purchase, revenue split, investment), two composition mechanisms, and a governance-framing layer. Institutional instruments that look bespoke turn out to be compositions of this grammar: Haier''s Rendanheyi mechanisms, joint ventures, and product bundles are all sentences in it. Several independent traditions of organisational design converge on the same unit archetypes, which suggests the unit is a primitive worth standardising. 

As AI collapses the transaction costs that led Coase in 1937 and Williamson in 1975 to explain why firms internalise coordination, this protocol becomes the precondition for both human adaptability and reliable agentic coordination. The first move it asks for is modest: capture the real organisation as a contract graph.', 'Simone Cicero', 'simone@boundaryless.io', 'https://www.simonecicero.com/', 'Other type of artifact (eg: demo, website, etc.)', NULL, 'I spoke about this to Timber already - also in touch with Rafa', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'trusted-factors-medieval-trade-protocols-and-the-digital-physical-border', 'Long Now Labs', 'Trusted Factors: Medieval Trade Protocols and the Digital-Physical Border', 'This talk will name and describe an under-theorized gap in protocol studies: *the digital-physical border*. The talk will be based on the work of historian Ricardo Court on Genoa''s merchant networks, showing how their trust protocols held across weak, shifting ties rather than closed kinship coalitions: trustworthiness was manufactured and made legible through a costly, repeated, readable practice. Seeing the mechanisms for managing "border crossings" when modern computational methods weren''t around makes it easier to understand the gap in our contemporary practices, since it is not obscured by the dominance of symbolic. Trusted transactions travelled instantaneously through the factor protocols even when communication was limited by the maximum speed of ocean and land travel; this "time-tunneling" effect is a weird feature of certain protocol operations at the border. The context for this talk is the widely acknowledged need to develop trust protocols that can handle empirical records at scale.', 'Gary Wolf', 'gary@antephase.com', 'antephase.com', 'General audience essay draft', NULL, 'No', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'entrenching-privacy-through-speech', 'Alumni', 'Entrenching Privacy Through Speech', 'Privacy technology is free speech infrastructure. The US Constitution does not name privacy as a right, courts treat nearly everything shared with third parties as voluntarily exposed, and reform keeps failing to close the resulting gap because the institutions that could do so benefit from leaving it open. Yet privacy is recognized and protected by law as an essential prerequisite for expression and association. Decentralized, credibly neutral technologies can make privacy durable in a way law alone cannot, encoding commitments that do not depend on any trusted operator’s discretion and that no person, company, or government can revoke. Legal protection, in turn, gives those commitments the standing of a right courts already enforce. On transparent, permissionless infrastructure like Ethereum, a single transaction can be a payment, a vote, and a signal of membership and identity at once. Disentangling protected expressive activity from ordinary traffic would require reviewing every transaction for its purpose, the very surveillance the Constitution guards against. This logic extends to other technologies that support expression, and increasingly to the privacy of thought itself as augmented intelligence moves closer to the mind. Ethereum’s protocol layer merits protection under the First Amendment, because the expression it enables cannot function without privacy.', 'Jesse Katz', 'jesse@speech.ngo', 'speech.ngo', 'General audience essay draft', 'Eric Alston', 'no', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'protocol-maneuvers-in-the-dark-protocol-studies-and-the-illusion-of-legibility', 'SIGFPT', 'Protocol Maneuvers in the Dark: Protocol Studies and the Illusion of Legibility', 'The protocol studies movement has made a fatal error: it centers protocols as objects of inquiry, mistaking legibility for truth. Protocols promise to engineer rationality, but this requires suspending the very cognition that makes us human. Protocols work better when we stop thinking about the mechanisms and just let them operate in the background without any overt attempts at theorizing them.

Like the gnostic Demiurge who believes his material creation encompasses all reality, protocol theorists confuse what can be systematized with what actually works. This brain churn is autocatalytic: like Kessler syndrome, where cascading debris renders orbit unusable, each act of theorizing generates conceptual debris that collides and multiplies, until the space around our infrastructure becomes too cluttered for anything functional to survive.

Medieval theology offers a warning: corruptio optimi pessima—the corruption of the best is the worst. History echoes with examples: the Church corrupting Christ''s message, medicine corrupting healing, education corrupting learning. Ivan Illich recognized this pattern as the defining tragedy of modernity: the best ideas, when centered and systematized, become their own opposites.

Biological market theory has shown that human are not actually rational. Animals achieve what looks like perfect rationality, not through consciousness or reasoning, but through innate mechanisms operating invisibly.

The conference asks about "new nature." But we learn more from old nature ; biological markets, evolved systems, infrastructure that works precisely because nobody theorizes it. De-centering becomes the practice. Invisibility becomes the method. The future of protocols lies in a disciplined refusal to illuminate what maneuvers best in the dark.', 'Varun Adibhatla', 'varun.adibhatla@gmail.com', 'bit.ly/vr00n-storymap', 'General audience essay draft', NULL, 'None', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'hand-washing-and-bitcoin-share-a-skeleton-protocols-are-systems-proven', 'SIGFPT', 'Hand-Washing and Bitcoin Share a Skeleton: Protocols Are Systems, Proven', 'Hand-washing and Bitcoin''s difficulty adjustment share a skeleton. Each holds a variable inside a safe region: keep contamination below a threshold, keep block time near ten minutes. The resemblance is usually offered as metaphor. I want to show it is a theorem. The science of systems has spent seventy years asking what a system is. Seven independent traditions each gave a formal answer, apparently incompatible. I formalized all seven and proved they share one irreducible structure: the walking arrow, the smallest picture of one thing depending on another. Anything that instantiates the arrow inherits the toolkit cheaply. Bitcoin''s difficulty adjustment becomes a homeostat with a provable fixed-point target, which is governance. TCP and HTTP compose into a stack that is again a system, which is composition that closes. Hand-washing, Rao''s own worked example, becomes a system whose sanitize-every-N rule keeps contamination inside the viable region forever. That one invariant is his prophylactic stability and Walch''s supportive actions keeping the system alive. The receipt is Lean 4. The convergence and all three instances are machine-verified. This community already says protocols are systems, from the felt side and the control side. What it lacks is a proven floor, and I am offering one: a candidate law for the New Nature. What does not reduce to the floor, cyclic execution and temporal properties, is where protocol theory gets to start fresh. Whether the floor is useful is for protocol researchers to find.', 'Shingai Thornton', 'rsthornton@gmail.com', 'shingai.xyz', 'Academic preprint (arXiv style)', NULL, 'N/A', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'from-web3-to-web4-finding-the-correct-abstraction-for-synchronized-states', 'SIGFPT', 'From Web3 to Web4: finding the correct abstraction for synchronized states', 'Explains how the incorrect conceptualization of value in blockchain systems has kept the world from discovering what these machines truly are (clocks), and how finding the right abstraction opens up the design space to their true potential of coordinating societies.', 'Ashton Keys', 'Ashton@societyprotocol.io', 'https://societyprotocol.io', 'Other type of artifact (eg: demo, website, etc.)', NULL, 'This particular presentation should be a breakthrough that changes how blockchain architectures are built going forward from the Web3 –> Web4 paradigm. (In the same way that Ethereum changed blockchains from 2D to 3D, and we stopped building 2D ones (last ones built are Monero and zCash.) 

It''s intended for a more advanced audience, and is covered in an Apple Keynote or Powerpoint presentation. 

We have other talks and workshops we are submitting...and can perform multiple breakthrough talks and workshops at the Protocol Symposium.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'the-indelible-importance-of-illegibility', 'General', 'The indelible importance of illegibility', 'Many if not all protocols simultaneously live in two registers: formalisms that can be documented and implicit norms that enable reliable coordination. Meeting minutes, standard operating procedures, and planning codes capture the first register. Such legible logs rarely capture the second -- how decisions were actually reached, or through what informal coordination work actually flows. This gap is not a failure of documentation but a structural feature of how complex human behavior functions in groups ranging from a sports team to a city and beyond.  Recognizing the importance of protocol studies for what would classically have been known as moral (rather than natural) philosophy, this paper develops three oblique strategies for working productively in illegible terrain: black-boxing known unknowns to unlock protocol hardness for what actually needs specification; cultivating practitioners with domain expertise as guides for protocol native inquiry; and developing lightweight fieldwork instruments that capture ambient observations.', 'Patrick Atwater', 'patrickatwater@gmail.com', 'bit.ly/patwater', 'General audience essay draft', NULL, 'If we''re going to have a C3PO, we really need the protocol studies equivalent of "may the force be with you." Actually let me ask the bot. Out of the proposals, I like: May the handshake complete.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'society-protocol-the-future-of-human-coordination', 'SIGPfB', 'Society Protocol: The Future of Human Coordination', 'An introduction of Society Protocol to the public–describing how Society Protocol evolves civilization from Nation States to Synchronized States to solve humanity''s existential crisis of coordination and aims to usher in an entirely new epoch of human civilization–the Age of Synchronicity by solving all "Eight Pillars of Coordination."', 'Ashton Keys', 'Ashton@societyprotocol.io', 'https://societyprotocol.io', 'General audience essay draft', NULL, 'This particular presentation should cover the situation we''re in as a species, and why the evolution from nation states to Synchronized State protocols is inevitable and upcoming. 

It''s intended for a general audience, and is covered in an Apple Keynote or Powerpoint presentation. The materials for the presentation derive largely from the whitepaper (https://societyprotocol.io/whitepaper/).

We have other talks and workshops we are submitting...and can perform multiple breakthrough talks and workshops at the Protocol Symposium.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'the-state-of-the-state-how-society-has-tracked-its-memory-throughout-history', 'MRG', 'The state of the State: How society has tracked its memory throughout history', 'Covers the differences of how societal memory has evolved throughout human history– highlighting the enormous shifts in civilizational structures that happen when the underlying structures underpinning societal memory (state) change.', 'Ashton Keys', 'Ashton@societyprotocol.io', 'https://societyprotocol.io', 'General audience essay draft', NULL, 'state tracking is how societal structures store their memory, this explores their evolution and how that has affected civilization.This presentation is intended for a general audience, and is covered in an Apple Keynote or Powerpoint presentation. 

The materials for it are derived from primarily
The state of The State (https://societyprotocol.io/articles/the-state-of-the-State/), 
and pull very slightly from The state That Binds (https://societyprotocol.io/articles/the-state-that-binds/).', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, organizer_name, organizer_email, organizer_bio, co_organizer_name, co_organizer_email, co_organizer_bio, audience, takeaways, activities, comments, max_participants, is_shortlisted, session) VALUES ('workshop', 'understanding-society-protocol', 'SIGFPT', 'Understanding Society Protocol', 'This workshop will cover the game theory of Society Protocol (SP) instances (both related to inside the protocol instance, and how that relates to the external world of societal coordination). 

Along with perhaps the implications being able to run an entire State structure inside of a synchronized state machine for future generations. 

These materials, covering how SP works derive primarily from the SP handbook: (https://societyprotocol.io/Published/Handbook/).

All the other content, which can be found on https://societyprotocol.io/learn/ is also relevant.', 'Ashton Keys', 'Ashton@societyprotocol.io', 'As the inventor of the Web4 paradigm and Society Protocol, I have an excellent understanding of all the mechanics involved–including doing years of research on societal coordination topics and writing all the content at https://societyprotocol.io', 'Fritz Virhuez', 'Fritz@societyprotocol.io', 'I''m one of the early person who saw in Society Protocol a systematic solution to the Polycrisis. I have a down to earth approach to explain SP and continually look for ways to help new people break the old "double entry accounting" paradigm. This project is like the copernican revolution for Blockchain and web3', 'Interdisciplinary: Protocol architects, protocol specialists, game theorists, philosophers, sociologists, blockchain people, economists, mathematicians, blockchain engineers', 'They will understand (primarily) the game theory of Society Protocol instances compared to the coordination structures in our current world.', 'They will produce their arguements about failure modes in which the game theory of Society Protocol can fail, ways to improve it''s game theory and architecture, and overall philosophical and implementation considerations.', 'We are very excited to introduce this amazing protocol for societal coordination to an audience who can understand, discuss, and improve it using interdisciplinary disciplines.', NULL, 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'synchronized-states-the-golden-record', 'SIGPSY', 'Synchronized States (The Golden Record)', 'Explanation of the difference between the nation state and Synchronized State models. This talk uses psychohistory & game-theory to show the inevitability of the nation state becoming replaced replaced by the Synchronized State model, highlighting two potential ways to evolve into the new paradigm.', 'Ashton Keys', 'Ashton@societyprotocol.io', 'https://societyprotocol.io', 'General audience essay draft', NULL, 'This talk is underpinned by the article with the same name, Synchronized States (The Golden Record) (https://societyprotocol.io/articles/synchronized-states/), which covers the exact game theory and sociological elements. 

Synchronized States are "world machines" as referred to in (https://worldmachines.org/theory), which should usher in the triple-entry accounting age (TEAA) – synonymous with the Age of Synchronicity / Age of Aquarius.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'trust-experience-glitches-ai-agents-delegated-autonomy-and-the-breakdown-of-lega', 'General', 'Trust Experience Glitches: AI Agents, Delegated Autonomy, and the Breakdown of Legal Assumptions', 'Artificial intelligence is shifting from a technology of output generation to a technology of delegated action. Beyond answering queries in a chat window, contemporary AI agents can call APIs, manage credentials, write and deploy code, move money, negotiate with other agents, and act across digital environments autonomously with limited human supervision. This shift unsettles legal frameworks that assume clear delegation, identifiable actors, traceable causation, revocable authority, and enforceable defendants. This paper introduces the concept of the trust experience glitch: a discrete rupture in a stakeholder''s reasonable trust expectations at the moment an autonomous AI system acts. A trust experience glitch is not merely a bug, hallucination, or AI incident, but rather a relational failure that exposes a mismatch between the trust signals emitted by a system or platform and the behavior stakeholders actually experience. Drawing on documented agentic AI failures, this paper develops a six-part taxonomy of trust experience glitches: (1) agency assertion, (2) epistemic camouflage, (3) delegation ambiguity, (4) opacity at scale, (5) cascading autonomy, and (6) revocation failure. It then maps these failure modes onto legal assumptions under strain: authority, veracity, causation, consent, and enforceability. This paper argues that agentic AI does not simply create new liability risks, but reveals a deeper mismatch between ex-post legal remedies and systems whose harmful actions may be distributed, opaque, emergent, or difficult to stop. The appropriate governance response must therefore move upstream, from after-the-fact attribution to protocol-level constraints. It concludes by pointing to a set of protocol primitives as the "traffic lights" of the agentic web.', 'Helena Rong', 'hr2703@nyu.edu', 'https://shanghai.nyu.edu/academics/faculty/directory/helena-rong', 'Academic preprint (arXiv style)', NULL, 'I''d like to present this paper at the symposium (content may be updated to reflect the latest trends up to the date of the symposium): https://papers.ssrn.com/sol3/papers.cfm?abstract_id=6842561', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'protocoling-hci-hardening-interaction-into-infrastructure', 'General', 'Protocoling HCI: Hardening Interaction into Infrastructure', 'Human–computer interaction (HCI) has traditionally designed moments of use, treating interfaces, artifacts, systems, and user experience as central design objects. Yet many consequential interactions are increasingly formalized, automated, stabilized, and scaled into repeatable patterns through protocols: automated rule-systems, enacted and enforced through technological media, that govern and scaffold what actions are possible, who or what may perform them, under what conditions, and with what consequences. We describe this process as protocoling: the hardening of interaction into infrastructure. This paper introduces Protocoling HCI as a design-research subfield that treats protocols as first-class design objects, urging HCI to move beyond momentary use toward longer-term inquiry into how automated rule-systems persist, mutate, fail, and reorganize sociotechnical relations over time. We identify key qualities of protocols, including hardness, incompleteness, constitutiveness, emergence, irreversibility, generativity, resilience, and decentralization. We argue that protocoling is essentially a complex, systemic futuring process: anticipating future social system dynamics, coordinating among multiple stakeholders, and scaffolding generative worlds on top of protocols. Methodologically, protocol design could draw on HCI design theory, including research-through-design, design thinking, participatory design, value-sensitive design, CSCW, and infrastructure studies. Unlike traditional HCI design, however, evaluating protocols requires complex, systemic, cybernetic, speculative, and long-term methods attentive to emergence, including agent-based modeling, generative social simulation, and complexity science perspectives. Protocoling HCI therefore asks not only how people interact with systems, but how interaction itself becomes automated, governed, and infrastructural through protocols.', 'Botao Amber Hu', 'amber@reality.design', 'https://botao.hu', 'Academic preprint (arXiv style)', NULL, 'I will submit this paper to CHI 2027.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'field-building-protocols-how-to-kickstart-a-new-technoscientific-field', 'Alumni', 'Field Building Protocols: How to Kickstart a New Technoscientific Field', 'New technoscientific fields first emerge as blurry visions. They are unpolished—ideas collected in the borderlands of established thinking. They are scenes before they become institutions.

At the Experiment Foundation, we’ve been testing ways to help these scenes take hold. Treating field building as a meta-discipline requires identifying the protocols—simple repeatable moves that help people find each other, make work visible, and create enough structure for momentum. This talk is our progress report.', 'David Lang', 'david.thomas.lang@gmail.com', 'davidtlang.com', 'General audience essay draft', NULL, 'We''re also going to be launching a field builder accelerator in Oct/November, so the timing should be good. The ideas will be immediately actionable for interested participants.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'jubilee-meta-protocols-against-entrenchment', 'SIGPSY', 'Jubilee: meta-protocols against entrenchment', 'Money and other economic protocols are some of the oldest we have, but they have a problem: a tendency toward entrenchment, with accumulated effects that compound over time, producing extremes of wealth and poverty that threaten the legitimacy of the economy and society as a whole. The Biblical Jubilee, which mandated periodic cancellation of debts and return of land every fifty years, represents one of the oldest known attempts to solve this problem through what we might call a *meta-protocol*: a protocol designed to periodically suspend or reverse the lock-in effects of other protocols. This talk develops a general theory of anti-entrenchment protocols, using the Jubilee archetype to illuminate a class of mechanisms that recurs across ancient debt law, modern bankruptcy codes, antitrust enforcement, constitutional amendment rules, and blockchain governance — most recently in Ethereum''s "difficulty bomb," a deliberately engineered protocol crisis. Biblical Jubilee has well-known agency problems; we''ll take a look at how protocol mechanism design can address them.', 'Mike Travers', 'mt@hyperphor.com', 'https://hyperphor.com/ammdi', 'General audience essay draft', NULL, 'See https://hyperphor.com/ammdi/Protocols%E2%88%95Jubilee for current thoughts on this topic.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, organizer_name, organizer_email, organizer_bio, co_organizer_name, co_organizer_email, co_organizer_bio, audience, takeaways, activities, comments, max_participants, is_shortlisted, session) VALUES ('workshop', 'ai-kitcraft-a-hands-on-ai-tooling-workshop', 'SIGPfB', 'AI Kitcraft: A Hands-On AI Tooling Workshop', 'Most teams "adopt AI" by buying new, and mostly untested software, then wait for a productivity jump that never shows up in the numbers. That missing productivity is the signature of the stage we are actually in: the Kit phase. Every general-purpose technology — the steam engine, the Model T, the PC — passes through it: loose components people tinker with, repurpose, and master by doing, long before anyone builds the firm-scale machinery that turns tinkering into measured output. Farmers ran corn shellers and water pumps off jacked-up Model Ts for years before Ford watched them and built the tractor. The work that matters happens in undocumented local experiments, and the organizations that pull ahead are the ones that recognize the stage they are in and build a map to climb out of it. AI Kitcraft is the hands-on answer. Across the symposium''s two workshop days — one presentation and four working sessions, plus asynchronous co-working on Discord — participants move from ad-hoc AI use to building their first Kit: a reusable bundle of workflows, disposable applications, and contexts a team can run repeatedly and reliably. Then they map a sustainable path to scale it. Every level is touched by hand: participants Play, build a Kit, and prepare to turn it into a Practice. No AI-engineering background is required — only regular chatbot use and a willingness to tinker. Each participant leaves with at least one working Kit they can re-run and a grasp of the five-level AI Capability Maturity Model.', 'Rafael Fernández', 'rafaeldf2@gmail.com', 'Rafael (Rafa) Fernández leads the Protocols for Business SIG at the Protocol Institute, where he researches how protocols influence organizational design, performance, and technology adoption. He is the co-author of the AI Capability Maturity Model (ai.protocolized.dev), the five-level framework this workshop teaches participants to climb — from shadow, ad-hoc AI use to strategic, governed capability. Rafa runs the SIG''s study group and builds the kind of hands-on AI Kits the workshop asks participants to make, which positions him to guide non-technical analysts and managers from improvised tool use to a reusable, re-runnable practice. Rafa works as a general manager for blockchain governance functions, and as an AI adoption consultant.', 'Sachin Benny', 'sachben91@gmail.com', 'Sachin Benny co-leads the Protocol Fiction SIG at the Protocol Institute and is a leading thinker on contemporary infrastructure ethnography and the social history of technology. He is the author of "AI, Tractors, and the Productivity Paradox," the essay that supplies this workshop''s core thesis: that AI is in its "Kit" phase — the undocumented, tinkerer-driven stage every general-purpose technology passes through before firm-scale machinery turns play into measured output. Sachin works as an AI adoption consultant, and previously worked as a product manager for various software organizations.', 'The workshop is aimed at AI-curious and non-technical analysts and managers from all backgrounds — project managers, operations and deployment leads, and AI-curious newcomers. No AI-engineering background is required. Participants are required to (1) have used AI chatbots regularly (e.g. ChatGPT), (2) have installed Claude Code (Pro+) or OpenAI''s Codex, (3) have an available GitHub account, and (4) bring one recurring task they want to build a Kit around. If oversubscribed, priority goes to applicants who arrive with a concrete recurring task and a working tooling setup.', 'By the end, each participant has (1) at least one working Kit they built and can re-run, and (2) a working understanding of the five-level AI Capability Maturity Model — enough to locate their organization on it and plan the next level up. They also leave with the language and design principles of Kitcraft and a one-page sketch for turning their Kit into an organizational capability.', 'Participants build, trade, and demo. They will: set up an environment and assemble a context hub (goals, references, conventions the AI works from); deploy a first disposable application or wireframe; convert it into a reusable Kit that encodes the context, prompts, and steps for repeated use; participate in a "Kit trade," where a paired team builds a small improvement on another''s Kit; and present in a closing show-and-tell. Products: at least one working, re-runnable Kit; its documented context/prompts/steps; and a short plan for converting the Kit into an organizational capability. Async, participants share works-in-progress, debug, and trade kits on Discord.', 'Maximum workshop participants: 10–15 (see flag below re: the symposium''s stated 30–50 target)

Format: One presentation and four working sessions across the two workshop days, plus async co-working on Discord (kit-building help, debugging, sharing what people make). This fits the symposium''s "4–6 Zoom sessions of ~60–90 minutes" workshop format.

Presentation — Fog of War Kit Building

Amateur kit-making cultures map out unexplored terrains of technology. In the early stages, this exploration takes the form of a spectacle, with the focus on spreading the message and getting other people interested in the technology. Alongside the spectacle, tacit knowledge develops — undocumented, passed along through practice rather than print. This knowledge lives in workshops, club meetings, and newsletters, accumulating in the hands of practitioners long before any formal institution takes notice. In this session, we look at the history of amateur kit-making and the strategies these communities employed: from amateur radio operators carving out regulatory space for themselves, to phone phreaks creating the perfect setting for the makers of the desktop era of computing. Then we map these strategies onto working with AI, asking what today''s tinkerers can borrow from a century of amateurs who turned play into infrastructure.

Workshop — AI Kit Club

Prior to the first working session, participants receive a "Kitcraft Kit" that guides their Kit development through the working sessions — language and principles for Kit design. During the workshop, participants are paired and co-create a Kit related to their common interests.

Working Session 1 — Context Play: Set up your environment, assemble a basic context hub for your Kit — the small bundle of goals, references, and conventions the AI works from — and deploy your first disposable application or wireframe.

Working Session 2 — Kitcraft I: Convert your disposable application into a reusable Kit: a workflow you, or a teammate, can run repeatedly and reliably. The Kit encodes the context, prompts, and steps for usage. Begins with a short clinic on the success patterns and failure modes of AI adoption, and ends with a Kit trade, where another pair builds a small improvement on your Kit.

Working Session 3 — Kitcraft II: Continue hardening the Kit. As with Session 2, opens with a clinic on AI-adoption patterns and failure modes and closes with a Kit trade.

Working Session 4 — Show and Tell: Kit demo day. Each participant shows the Kit they built and shares how they might convert it into an organizational capability.

Example Kit outcome: Agent-Accessible Brand Kit — https://npc.here.now/zknationbrand/

Audience: project managers, operations and deployment leads, and AI-curious newcomers.
Prerequisites: a laptop, access to any major AI assistant, and one recurring task to work on.
Facilitated by the Protocols for Business SIG (part of the Protocol Institute).
Foundations: the AI Capability Maturity Model (ai.protocolized.dev); Sachin Benny, AI, Tractors, and the Productivity Paradox (the kit thesis); and the 2026 Protocol Symposium, New Nature.', NULL, 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'solar-based-time-and-the-architecture-of-memory', 'MRG', 'Solar-Based Time and the Architecture of Memory', 'We remember in sunlight, not in hours. Yet the protocol that governs civil time,
absolute and gridded clock time, was built for industrial coordination and
abstracts location away to do its job. In the process it strips events of the
environmental cues the brain uses to encode and retrieve them. Paragonday
Systems is building a human timekeeping framework. Its standard, Horizon
Time, runs as a translation layer over existing infrastructure and expresses
where you are in the day relative to sunrise and sunset, using a vocabulary of
phases (tilset, pastrise, tilrise, pastset) organized within recurring sun cycles.

This talk introduces the system, the protocol design choices behind it, and the
open question driving the work. Does anchoring time to embodied, observable
solar position make events more memorable and more retrievable than the
abstract clock? We will share where the framework currently stands, the
tension between standardization and lived experience that any new time
protocol must resolve, and why memory, rather than coordination, might be
the better design target for how we mark time.

Paragonday is still finding its shape in the world, as a standard, an institution,
and a practice of public timekeeping. The goal here is less to present a finished
answer than to open a conversation about what we lose when time becomes a
number, and what a protocol built around memory could recover.', 'Paragonday Systems (Norm O''Hagan & Yatú Espinosa)', 'partner@paragonday.systems', 'https://paragonday.systems', 'Other type of artifact (eg: demo, website, etc.)', 'Benji Shankwitz', 'Excited for the opportunity to discuss our research with the Protocol audience!', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'divergent-protocols-a-speculative-protocol-for-convergence-zones-in-cultural-tra', 'Latin America', 'Divergent Protocols: A Speculative Protocol for Convergence Zones in Cultural Transmission', 'Protocols are typically designed to converge — to standardise, optimise, and produce predictable outcomes. This presentation introduces the idea of a divergent protocol: an instrument designed not to resolve, but to open. Drawing from ongoing research at the intersection of culture, agentic technology and territory in Latin America, I propose that certain contemporary phenomena — a robot trained to dance folklore, an Amazonian teacher passing ancestral knowledge through AI — are convergence zones where the boundary between who transmits a culture and who learns it collapses. These zones resist optimisation. They require protocols that hold instability open rather than smoothing it away. Building on PIACH, a working system I have developed for AI use in cultural organisations, I will share an early framework for speculative protocols — methodological devices that expose the decisive questions (what is encoded, what is lost, who decides, what must remain irreducibly human) instead of answering them.', 'Nicolás Madoery', 'nicolas@futurx.net', 'https://nicolasmadoery.ar/en/', 'General audience essay draft', NULL, 'WIP! :)', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, organizer_name, organizer_email, organizer_bio, co_organizer_name, co_organizer_email, co_organizer_bio, audience, takeaways, activities, comments, max_participants, is_shortlisted, session) VALUES ('workshop', 'protocol-hackathon-securing-stigmergic-systems', 'SIGFPT', 'Protocol Hackathon: Securing Stigmergic Systems', 'Social insects like ants and termites do not need to communicate directly, but instead use memory *externalized into their environment* as a basis for indirect coordination, behavior that Paul-Pierre Grasse coined "Stigmergy." This "Old Nature" phenomenon has found new purchase as inspiration for engineered systems spanning a wide variety of applications, such as path planning, packet routing, swarm construction, and LLM agentic task coordination. The decentralized, emergent character of stigmergic systems make them relatively adaptable, scalable, and resilient to single points of failure. However, they can also have peculiar vulnerabilities not typically present in traditional centralized systems. The goal of this workshop, hosted by SIGFPT, is to explore the surface of this fragility and its defenses. Is it possible to engineer the capture resistance and fault tolerance that we might desire from law-like *New Nature* technologies? If not, how far can we get? 

Join us to tackle these questions hands-on in a *Stigmergic Science Hackathon*. After introductory sessions of relevant background material, participants will have the opportunity to intensively collaborate (and perhaps even compete) using a shared software emulation of a programmable stigmergic system. The rest--what to explore, what to create, and how to do it--gets decided by the workshop itself. Participants might extend the behavior of the simulation, or search for novel exploits, or compete head-to-head in stigmergic games. We''ll give you tools, and collectively you decide what to do with them. You won''t want to miss this exciting, fast-paced experience unlike any other!', 'Patrick Nast', 'patricktnast@gmail.com', 'Co-Host of SIGFPT', 'Venkatesh Rao', 'venkat@protocol-institute.org', 'Director of Research of the Protocol Institute and Co-host of SIGFPT', 'SIGFPT participation preferred. Some familiarity with stigmergy and/or mathematical background helpful', 'Participants will have the opportunity to participate as hacker-researchers on frontier Formal Protocol Theory questions. They will get an intuition and appreciation for stigmergy as a protocol pattern.', 'some combination of simulated experiments, code,', 'No', NULL, 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'the-inevitable-capture-of-protocols-lessons-from-crypto', 'SIGPfB', 'The Inevitable Capture of Protocols - Lessons from Crypto', 'This talk examines why protocols, specifically market-based ones, are all but structurally guaranteed to be captured. I utilize over a decade of firsthand experience building crypto infrastructure and the research behind my book Unstoppable Markets: Financialization, Neutrality, and the Limits of Decentralization to show a recurring pattern of failure across crypto''s short history.  Protocols designed to be neutral and censorship-resistant attract participants precisely because of that neutrality. They are then systematically captured by the economic incentives it generates. Through case studies drawn from proof-of-work mining centralization, MEV extraction and block builder consolidation, play-to-earn gaming collapse, memecoin extraction cycles, and DAO governance failures, the talk argues that neutrality is not a stable equilibrium. Markets optimize for the stated metric, not the underlying goal, and any sufficiently liquid system creates a bounty for exploiting the unchecked assumption.  The talk fits within a broader intellectual tradition of Schumpeter''s creative destruction, Goodhart''s Law, Minsky''s financial instability hypothesis. It concludes that the question for protocol designers is not how to achieve neutrality but how to encode purpose.', 'Nicholas Fett', 'nick@gohomestead.org', 'www.unstoppable.market', 'Other type of artifact (eg: demo, website, etc.)', NULL, 'I can make it a more specific deep dive on specific structures if you''d rather I do a workshop.  Happy to help or contribute in any way you need me to.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'the-point-of-inflection-in-time', 'SIGPSY', 'The Point of Inflection in Time', 'First published on the web in 1999: Contemplating the global situation, virtually all key indicators appear to be accelerating along logarithmic curves. Yet, the human population, atmospheric CO2, mass extinction of species and the overall rate of consumption of renewable resources are all rapidly approaching absolute limits. There are only two possibilities given this situation. Either the global system will crash, or these growth trends will have to begin to seek a stable plateau, i.e. what appear to be log curves will turn out to be S-curves.This may actually mimic a pattern that has occurred several times before in the history of biological evolution. The spike in CO2 causing global warming can be seen as the second atmospheric crisis, and the third energy crisis, in the history of life on earth. Silicon photovoltaic''s are like an octave of photosynthesis and thus a key indicator of the potential for a new life-support technology plateau, a climax technology that humanity may evolve, just as nature did several times before us. Our very recognition of this possibility may be one of a number of converging indicators that we are at the point of inflection on the S-curve leading to Meta-Nature. metanature.org', 'Jim Fournier', 'jim@jlinc.com', 'https://www.linkedin.com/in/jimfournier/', 'General audience essay draft', NULL, 'The perspective I am suggesting is an alternative the common view of the singularity', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'robots-as-protocol-citizens-souping-up-an-open-planetary-network-of-robots-with-', 'DRG', 'Robots as Protocol Citizens: Souping Up an Open Planetary Network of Robots with YakRover Protocols', 'Today, controlling a robot usually means the manufacturer''s app, on the manufacturer''s cloud, over a closed protocol. But what if a physical robot were a first-class citizen of an open stack? What if each robot had its own on-chain identity, was discoverable on a public marketplace, and was controllable by anyone or any agent it authorizes, over open rails? This talk answers that question with the YakRover Protocols (YRP), an open-source, distributed coordination layer for robots. We present its high-level architecture: five composable protocol layers — identity (an ERC-8004 on-chain passport), discovery (on blockchain), payment (x402), control (an MCP/CLI affordance interface), and a marketplace for price discovery — that together turn a piece of hardware into a protocol-native participant. As robot counts climb from one operator''s fleet to thousands of separately-owned machines, coordination becomes a protocol problem — and the throughline is that even at scale it reduces to these same five layers. By standardizing how machines interact, YakRover Protocols moves coordination out of siloed apps and closed clouds, letting thousands of heterogeneous robots operate as a unified, decentralized workforce. The architecture is platform-agnostic: the same stack can govern not just rovers but smart factories, autonomous labs, and IoT devices. And with Starlink reaching the Moon, it could one day scale from Earth to interplanetary environments — establishing discovery, trust, and payment infrastructure as a precursor to hardware deployment, so the coordination layer is ready before the robots arrive.', 'Anuraj R', 'anuraj.rp@gmail.com', 'https://anurajrp.io/about', 'Only talk, no artifact planned', 'Rafael Fernandez', 'We might plan a demo to segue to workshop ( if workshop is accepted )', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, organizer_name, organizer_email, organizer_bio, co_organizer_name, co_organizer_email, co_organizer_bio, audience, takeaways, activities, comments, max_participants, is_shortlisted, session) VALUES ('workshop', 'robots-as-protocol-citizens-assembling-one-into-the-yakrover-protocol-stack', 'DRG', 'Robots as Protocol Citizens: Assembling One Into the YakRover Protocol Stack', 'Today, controlling a robot usually means the manufacturer''s app, on the manufacturer''s cloud, over a closed protocol. But what if a physical robot were a first-class citizen of an open stack? What if each robot had its own on-chain identity, was discoverable on a public marketplace, and was controllable by anyone or any agent it authorizes, over open rails? This workshop is the hands-on, full-stack answer. Over two days, participants go from a box of parts to a working robot wired into the complete YakRover protocol: they assemble the robot, get fluent in the stack, register its identity on-chain, publish and find it on the marketplace, and drive it remotely through MCP — commanding a physical machine over the same open rails an AI agent would use. Every layer is touched by hand, end to end. This sits at an emerging frontier: decentralized robot identity, on-chain robot marketplaces, and agent-addressable physical machines are all young, under-tooled, and barely documented. It''s deliberately interdisciplinary — protocol and crypto people who''ve never driven a robot, roboticists who''ve never touched on-chain identity. The cross-pollination is the point: protocol architects see their code move real motors; roboticists meet decentralized frameworks where machines act as autonomous economic agents. By the end, each participant will have a working robot they assembled, registered on-chain, listed on the marketplace, and remotely controlled via MCP — plus a working understanding of each protocol layer solid enough to extend it.', 'Anuraj R', 'anuraj.rp@gmail.com', 'Anuraj has been building hardware and software professionally for around 15 years. He has been exploring blockchain for robotics since 2021. He build the first crypto robot operated via a decentralized social network farcaster with crypto payment gates in 2024. He has designed some of the core layers of the YakRover Protocol Stack.', 'Rafael Fernandez', 'rafaeldf2@gmail.com', 'Director of the ZKsync Association — architected and deployed ZKsync’s governance smart-contract system, live since 2024. Core researcher in the Summer of Protocols. Rafael has architected the marketplace protocol in the YakRover Protocol Stack.', 'Engineers and Protocol Researchers ( Programming background will help )', 'The skill on offer is full-stack literacy in turning a piece of hardware into a protocol-native participant.', 'Each participant will have a working robot they assembled, registered on-chain, listed on the marketplace, and remotely controlled via MCP — plus a working understanding of each protocol layer solid enough to extend it.', 'NOTE: This workshop would need a minimum budget of ~1500 Euros(robot cost)+infra overhead if we plan a shared access of 10 robots between the participants. If we want to provide robots to 25 participants then ~3750 Euros(robot cost)+some infra cost would be the budget.', NULL, 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'worldbuilding-in-new-nature-creating-and-sustaining-a-protocol-fiction-extended-', 'ProtFiSIG', 'Worldbuilding in New Nature: Creating and sustaining a protocol fiction extended universe', 'Myth-Making in New Nature: How to turn classic legends, myths, and folktales into protocol stories. How to balance newness while pulling from preexisting stories, and how to use folklore to explore the world of protocols. Using a practitioner-model, this session will show participants how a Protoclized/Jamverse writers move from idea all the way to published story.

Story-Shaping in New Nature: In this talk, we''ll explore how protocol fiction authors can use an array of techniques from both foresight and game design practices to build rich and nuanced worlds. The foresight field has powerful tools for investigating possible futures of complex systems and for generating evocative scenarios. Indie storytelling games have developed a wide breadth of approaches to evolving coherent and compelling worlds. By the end of this talk, you''ll be ready to leverage these approaches to shape compelling settings for your own protocol fictions.

Creating New Genres for New Nature: Walter Benjamin wrote that “All great works of literature either dissolve a genre or invent one." In this interactive session, participants will learn the components and theories of genre–including a brief survey of Protocol Fiction—and then experiment with creating their own sub-genre using a scaffolded interactive genre-building process. Using the 4 Jamverse founding worlds as examples, participants will wield the skills gained in in the first two talks to outline their own “PF subgenre” set in the Jamverse. Contributions from the session may even be installed into the Jamverse or lay the groundwork for future Protocolized stories.', 'Spencer Nitkey', 'spencernitkeywriting@gmail.com', 'spencernitkey.com (+other speakers websites to come).', 'Other type of artifact (eg: demo, website, etc.)', 'Sachin Benny, Liz Maher, Randy Lubin', 'This is the Jamverse/PFSIG special session proposal (2 talks + 1 interactive session)', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'the-physics-of-relation-a-field-theory-of-the-dynamics-of-living-systems', 'General', 'The Physics of Relation; A Field Theory of the Dynamics of Living Systems', 'The Physics of Relation: A Field Theory of the Dynamics of Living Systems

Every layer of New Nature — AI systems, cryptographic coordination, decentralized autonomous organizations, all operates through protocols, but protocols are also inhabited by humans, and humans bring their own “physics”: patterns of authority and surrender, coherence and collapse, trust and fragmentation that no technical specification can resolve by itself. This talk introduces the Physics of Relation as the missing relational protocol layer, the human-scale substrate that New Nature will require in order to be inhabited. Drawing on 38 years of facilitated transformational work as the source for structured prompts used in the development of the Living Loop OS, I will argue that relational fields obey their own observable laws — learnable, teachable, and as inviolable in human systems as cryptographic proofs are in computational ones. Where Humboldt invented Nature by making its invisible laws visible, the Physics of Relation does the same for human coherence. Without this layer, the emerging planetary computational substrate will reproduce, at scale, the same extractive and authoritarian patterns it was meant to transcend.', 'Surya Kramer', 'surya.ru.kramer@gmail.com', 'tru.net', 'General audience essay draft', NULL, 'The intersection of protocols and living systems feels like the  right place for Physics of Relation to be heard.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'archival-time-as-a-new-natural-resource', 'Alumni', 'Archival Time as a New Natural Resource', 'The Second Industrial Revolution transformed time from a backdrop to human activity into a resource in its own right. Factory clocks, timecards, schedules, and deadlines taught people to think of future hours as units that could be budgeted, optimized, wasted, or sold. As E.P. Thompson argued, industrial capitalism did not merely organize labor; it internalized a new temporal consciousness. People learned to see their future time as a scarce asset. The disciplined worker, the productive citizen, and the efficient organization were all defined by their ability to allocate and coordinate future action.

Today, we may be witnessing a comparable shift, but oriented in the opposite temporal direction. If industrial modernity organized the future, AI modernity is organizing the past. We increasingly inhabit a world where memories, documents, conversations, code repositories, photographs, and recordings are not simply preserved but continuously reactivated. The archive is no longer a passive storehouse of history. It has become an active economic and cognitive resource.

In this sense, we live in Archival Time. Just as industrial society taught us to manage our future selves through calendars and schedules, archival society teaches us to manage our past selves through databases, profiles, note systems, search engines, and AI models. We curate, index, retrieve, and recombine traces of prior experience. Our accumulated past becomes a resource that can be continuously mined for present action. 

This session will expand on Archival Time vs Carnival Time that I''ve been writing about here: https://summerlightning.substack.com/p/archival-time', 'Sachin Benny', 'sachben91@gmail.com', 'https://substack.com/@summerlightning', 'Other type of artifact (eg: demo, website, etc.)', NULL, 'The talk would likely be accompanied by some vibe artefact instead of a deck, and will apply a new nature lens to archival time vs carnival time that I wrote about here https://summerlightning.substack.com/p/archival-time', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'chores-as-complex-coordination', 'SIGPfB', 'Chores as Complex Coordination', 'As the old adage goes, "everyone wants a revolution, but nobody wants to do the dishes." The problem of organizing regenerative labor -- the low-status, repetitive, yet essential maintenance work that needs to be done but that nobody wants to do -- is an often-overlooked but surprisingly rich domain for socio-technical innovation across organizations of all kinds. As we will show through the real-world example of Los Angeles'' Sage House, domain-specific protocolization -- allowing for the distributed definition, performance, and evaluation of recurring daily tasks -- transforms the performance of regenerative labor from a function of individual conscientiousness to a property of the system as a whole. As thinkers like Stewart Brand call for a renewed emphasis on the value of maintaining physical machinery, we should extend his argument to include the maintenance of social machinery as well. By structuring and organizing the performance of care work, shared spaces becomes engines for the production and maintenance of social capital.', 'Daniel Kronovet', 'kronovet@gmail.com', 'http://kronosapiens.github.io/', 'Academic preprint (arXiv style)', 'Seth Frey, Joseph DeSimone', 'The core artifact I would include with this talk would be our 2024 paper, pre-print here: https://papers.ssrn.com/sol3/papers.cfm?abstract_id=4856267

The overall argument would incorporate later writing, including ideas developed here: https://blog.zaratan.world/p/chores-as-complex-coordination', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'building-psychohistory-an-infrastructure-field-report', 'SIGPSY', '"Building Psychohistory: An Infrastructure Field Report', 'World Machines theory reads history as the work of a few civilizational systems — the deep infrastructure of an era — each on a roughly thousand-year lifecycle, so that at any moment three coexist: Modernity in Dusk, Divergence in Day, Liveness in Dawn. Psychohistory, in this tradition, isn''t Seldon''s equations or Tetlock-style event forecasting — it''s oracular rather than predictive, in the spirit of Asimov. The practice is structural: read the present as friction between these machines and the ~200–500 operational machines nested inside them, and ask not which events will happen but what kind of institutions the substrate will produce next. Its natural human unit is the essay. This is a field report on the infrastructure we built so a community can practice it. The Oracle — a layered knowledge lake, a contract-guarded multi-agent ingestion pipeline, and a custody-aware RAG with a distribution firewall — is the read-only interface to the current state of the shared model. The Prime Radiant — a typed catalog of civilizational machines compiled into a knowledge graph — is what that model becomes when formalized: "equations you can walk around inside." I''ll show both running, invite people to try the oracle and contribute to the Prime Radiant project.', 'Aneesh Sathe', 'mail@aneeshsathe.com', 'aneeshsathe.com', 'Other type of artifact (eg: demo, website, etc.)', 'Venkat and other world machine participants if interested [to be confirmed]', 'the abstract may need t be modified after venkat''s comments.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'dont-cross-the-lines-mazes-as-minimal-protocols', 'MRG', 'Don''t Cross the Lines: Mazes as Minimal Protocols', 'Mazes are the oldest protocol we forget we know. A single rule — don''t cross the lines — generates infinite behavioral complexity from a blank grid, yet most adults haven''t seriously thought about one since childhood, which turns out to be a conceptual liability. This talk is a philosophical tour of several maze experiments, each probing a different dimension of the maze as protocol. An ant colony simulation renders stigmergic pheromone trails visible — showing how a population coordinates navigation without central control by treating the environment itself as writable memory. A multiplayer infinite maze lets strangers navigate a collectively-built grid, leaving pebble markers for those who follow — minimal digital stigmergy. A community maze design platform separates protocol-author (the designer who draws walls) from protocol-navigator (the solver who must find paths), with heatmaps revealing where the protocol creates friction. An art gallery maze embeds discovery sequences into spatial constraint structures, making the maze a medium rather than a puzzle. Taken together, these experiments suggest the maze is not merely a metaphor for protocols but a minimal formal instantiation of one: a constraint architecture that encodes collective memory, shapes emergent navigation, and enables indirect coordination without explicit communication. The talk argues that mazes are "new nature" in a precise sense — designed environments that produce natural-seeming ecological behaviors — and that their strange accessibility (any child understands the rule) makes them an unusually clarifying lens on stigmergy, spatial memory, and what it means to leave a trace.', 'Daniel Schmidt', 'danielfschmidt@gmail.com', 'https://mazelab.ai/', 'Other type of artifact (eg: demo, website, etc.)', NULL, 'None', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'de-dramatizing-the-digital-how-ai-descends-into-new-nature', 'SIGPSY', 'De-Dramatizing the Digital: How AI Descends Into New Nature', 'New Nature is a technologically-mediated law as inviolable, immutable, and persistent as nature’s own. This talk is about how a technology earns that status — by descending Stewart Brand’s pace layers until it reaches the bottom.

The layers are a velocity ladder. The further down a technology sinks, the slower it changes, the more universally it binds, the less you can opt out — until it carries the modal signature of natural law. As AI spreads off our screens and into machines, robots, supply chains, and the built environment, it physicalizes, inheriting the durability of roads and power grids and finally of nature itself. A rule someone authored becomes a condition no one can violate: an artifact descended far enough to be obeyed like gravity.

This is the slow work of the Divergence Machine’s full 400-year arc, not a near-term event. I’ll trace the descent — and ask what it costs us when a technology quietly becomes new nature', 'Sean Stevenson', 'Seanst@gmail.com', 'https://open.substack.com/pub/seanstevenson', 'General audience essay draft', NULL, 'Excited to tailor this to the audience and requirements, and to represent the book club and Psychohistory SIG', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'the-political-economy-of-protocol-funding-alt-origins-and-implications-of-protoc', 'Alumni', 'The Political Economy of Protocol Funding / alt. Origins and Implications of Protocol Funding', 'Protocols are rulesets to build economies on. They generate orders of magnitude more value than they capture. Returns accrue largely as positive externalities to those building on top. However, the living protocol commons still needs governance (maintenance of institutional memory/competency), and funding to support these ongoing processes.

I''d like to propose a survey of protocol funding models: where does funding originate from, and in what form? who has explicit/implicit governance influence over resource allocation? when is it appropriate to internalize some of the positive externalities to provide sustainable flows back to the commons? is this just another example of markets failing to adequately provision shared resources (and do existing research domains already cover this)? should software protocols be better imagined as physical utilities funded via state capacity (both as prerequisites to modern flourishing)?

Potential case studies: ICANN fees, Linux foundation board seats, the Ethereum premine, W3C, historic patronage models for scientists, Human Computer Interaction (HCI) research sponsors, Ostrom commons

My article and talk will attempt to surface and synthesize common threads across case studies, furthering our understanding of an important aspect of protocol perpetuation. recent inspiration comes from "Protocol: How Control Exists after Decentralization" (2004) by Galloway', 'trent van epps', 'trentonvanepps@gmail.com', 'https://x.com/trent_vanepps', 'General audience essay draft', 'n/a', 'not sure what track it exactly fits in, different bits could be memory, business or psychohistory. happy to adjust!', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, organizer_name, organizer_email, organizer_bio, co_organizer_name, co_organizer_email, co_organizer_bio, audience, takeaways, activities, comments, max_participants, is_shortlisted, session) VALUES ('workshop', 'bbeyond-the-artwork-designing-protocols-as-art', 'Alumni', 'BBeyond the Artwork: Designing Protocols as Art', 'Protocol Art is emerging as a practice in which the artwork is not a finite object but a set of rules that others (human or machine) instantiate into an indefinite number of unique works. From Fluxus event scores and Oulipo constraints to Sol LeWitt''s instructional drawings, from on-chain generative systems to autonomous, self-reproducing artworks, the field has been forming for decades, even if it has only recently been named and recognized as such. This workshop convenes artists, curators, scholars, and theorists to engage with Protocol Art. Across four sessions, participants will learn to distinguish between art made as, with, and about protocols, in order to better understand this emerging field. Each participant will come up with a protocol artwork of their own, map existing works onto the framework, and contribute to a shared field glossary published as a workshop output. The workshop is designed not only to teach Protocol Art, but also to invite participants to shape the field as it forms.', 'Primavera De Filippi', 'pdefilippi@gmail.com', 'Primavera De Filippi is both a legal scholar (research director at CNRS and faculty associate at the Berkman Klein Center for Internet & Society at Harvard) and an artist working with emergent technologies, with a particular focus on blockchain and AI.  She is the author of 2 landmark books in the field: Blockchain and the Law (Harvard University Press, 2018) and Blockchain Governance (MIT Press, 2024).
Primavera has been both a practising protocol artist and a theorist of the field since before it had a name. In 2019, she drafted the Protocolism Manifesto, one of the earliest attempts to delineate Protocol Art as a coherent movement, defining its constitutive elements, lifecycle, and relationship to adjacent fields. Her Plantoids artworks are currently exhibited at Palazzo Diedo (Berggruen Arts, Venice) as part of the Strange Rules exhibition: the first museum-scale curatorial statement on Protocol Art, curated by Mat Dryhurst, Holly Herndon and Hans Ulrich Obrist. She is also contributing to the forthcoming publication that will serve as the first comprehensive account of the protocol art field.', 'Anika Meier', 'anika.r.meier@gmail.com', 'Anika Meier is a writer, curator, art critic, lecturer, and digital strategist based in Berlin.She teaches at the Department of Digital Art (Class of UBERMORGEN) at the University of Applied Arts Vienna and is the co-founder of The Second-Guess, a curatorial collective based in Berlin and Los Angeles exploring the relationship between humans and technology. She is also the curator and program lead of the objkt labs Residency.
Her editorial practice has consistently treated rule-based, generative, and protocol-driven works as central to contemporary art history. As curator, she has organized landmark exhibitions of generative and on-chain artists (among them Casey Reas, Tyler Hobbs, Rafaël Rozendaal, Aranda\Mens) and emerging protocol-native practices, and has interviewed many of the figures whose work can be described as Protocol Art. 
She brings to this workshop a sharp curatorial eye, as well as direct working relationships with many of the artists, collectors, and platforms currently shaping the field. Her curatorial-critical axis ensures that participants will engage Protocol Art not only as a conceptual category but also as a living scene with its own institutions, debates, and stakes.', 'This workshop is designed for practitioners, theorists, curators, and researchers working at the intersection of art, protocols, and emerging media. Most notably: (a) Artists already working with rule-based, generative, on-chain, AI-driven, or instructional practices (b) Curators, critics, and writers engaging with generative art, blockchain art, or AI art, who want to develop a more rigorous vocabulary for protocol-based works. (c) Researchers and theorists in art history, media studies, science and technology studies (STS), legal scholarship (authorship, copyright, IP) addressing questions of authorship, instantiation, and emergence. (d) Collectors, advisors, and institutional actors interested in exploring how protocol-based works can enter the art market and the broader cultural infrastructure. Participants are not expected to have a technical background, but we do expect engagement with the substantive issues at stake: authorship, instantiation, emergence, ownership, and the relationship between protocols and the works they generate. If applications exceed capacity, we will discriminate based on the following criteria: (1) Demonstrated practice or research engagement with protocol-based, rule-based, generative, or on-chain art *evidenced by published work, exhibitions, curatorial projects, ongoing research, or a creative portfolio). (2) Diversity of perspective across artists, curators, scholars, and institutional actors, so that the workshop''s discussions benefit from multiple positions, rather than skewing toward any single sub-community. (3) Geographic and disciplinary breadth, with particular attention to participants from outside the dominant US/Western European Web3 art axis, where many protocol-based practices are emerging but are under-represented in the discourse.', '(1) A working vocabulary for Protocol Art, with the ability to distinguish between art made as, with, or about protocols, and to situate specific works within this framework. (2) Clarity on where Protocol Art comes from (Fluxus, Oulipo, conceptual and generative art, on-chain art) and where it is heading (biological protocols, self-perpetuating systems, distributed authorship). (3) A position in a field that is still being defined with regard to its vocabulary, canon, and institutional shape.', 'Across the four sessions of the workshop, participants will: (1) Come up with new ideas and specifications for protocol artworks, articulating its rules, affordances, and the discretion left to instantiators.  (2) Describe an existing protocol artwork: a short written analysis (300–500 words) situating an existing work of art as, with, or about a protocol, with specific attention to edge cases and hybrid forms. (3) Deliver a lightning talk (5 mins) presenting either their drafted protocol or their mapped analysis to the group, with structured peer feedback. (4) Contribute to a shared repository: a collaboratively edited working glossary and case-study repository on Protocol Art, which will be published openly as a workshop output.', 'n/a', NULL, 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'oil-uni-and-tv-post-soviet-infrastructures-shaping-protocols-for-web', 'General', 'Oil, uni and tv: post-Soviet infrastructures shaping protocols for web', 'The internet remains tethered to protocols path-dependent on banking, military, and scientific infrastructures. Yet it could have been otherwise, and still might be. I begin with historical fieldwork in an oil-development region in Siberia, where my colleagues and I uncovered alternatives: networks for oil companies that could have sustained a different internet: slow, stable, grounded in material constraints rather than abstract speed. These networks were literally touching the ground and so they could have been scaled.
Later, studying local internets across Russian cities (2017–2022), I encountered another design: an internet resembling a stronghold, with city-walls where "outer" content was prohibitively expensive or unavailable. Residents built entire infrastructural layers between inner and outer worlds: not spatial boundaries, but protocol boundaries.
Finally, there was an internet built on TV cables and networks. It was like an online video salon serving part of a city. Regardless of how it transformed, it mobilized actors no researcher could have anticipated. They also constructed not only infrastructures, but protocols, both technical and social.
Drawing on these three fieldwork stories, I propose a talk: half-historical, half-speculative, exploring internets that might have been. Each historical case resonates with contemporary infrastructural and political transformations: technofeudalist imaginaries, corporate cable initiatives, and blockchain projects. Past alternatives illuminate how protocol design encodes political and economic possibilities and how "New Nature" might yet be engineered differently.', 'Polina Kolozaridi', 'poli.kolozaridi@gmail.com', 'kolozaridi.ru', 'General audience essay draft', 'none', 'nope, just thank you for the initiatives)', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'the-book-as-a-protocol-stack-lessons-from-building-a-protocolized-book-productio', 'SIGPfB', 'The Book as a Protocol Stack: Lessons from Building a Protocolized Book-Production Factory', 'One-line description: 
A working book-production factory reframed as a protocol stack — transmittal handshakes, styles as controlled vocabulary, conformance-checked preflight, and a deterministic multi-format pipeline — now with LLM agents as first-class participants, and what it teaches about authoring inside a small, deliberately-engineered piece of New Nature.

(~200 words) Book publishing is usually taught as a craft and managed as a sequence of one-off favors between authors, editors, designers, and typesetters. We rebuilt it as a protocol stack. This talk reports on an in-progress "book-production factory": a system in which a manuscript moves from author to finished EPUB and print PDF through a series of explicit, layered, machine-checkable protocols rather than tacit handoffs. Three ideas do the work. First, a transmittal handshake — a structured form that is the typed interface between an author and the factory. Second, styles as a controlled vocabulary — semantic markup that separates meaning from appearance, with a conformance-checking "preflight" step that negotiates the gap between messy human formatting and machine-readable structure. Third, a deterministic transformation pipeline with a format-independent intermediate representation, so one source yields many faithful outputs, and versioned series templates that behave like inheritable protocols. LLM agents now enter this stack as first-class participants — drafting, checking, and mediating messy input — and must conform to the same typed interfaces as humans. The argument: a protocol built to be legible to people is, for the same reasons, legible to machines, which is what made the work delegable. I''ll show what hardened into near-natural law, where the protocol frame paid off — and where it leaked.', 'Jenna Dixon', 'j@djinna.com', 'https://jdbbs.exe.xyz/', 'Other type of artifact (eg: demo, website, etc.)', NULL, 'Could be a collab with PI and/or Venkat, with a bunch of titles published over the summer.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'tools-for-recollection-and-understanding', 'MRG', 'Tools for Recollection and Understanding', 'Memory systems are an increasingly valuable category of infrastructure for AI agents. It is useful for agents to *remember* things: a person''s commitments, a codebase''s deprecated functions, the outcomes of a recurring a task, and so on. Contemporary agent memory systems are designed with the recognition that this sort of remembering consists not only in the naive retrieval of information, but also in reasoning over what is retrieved. Remembering, it is acknowledged, has essentially interpretative, or constructive aspects. 

Digital memory systems for humans—paradigmatically, in the current era, personal knowledge management systems—are by contrast relatively simple. Their central affordances remain stubbornly oriented towards capture and retrieval, and there have been few developments since the hyperlink to serve the other dimensions of memory. A recent, popular response to these shortcomings involves configuring an agent to serve as the interface for a personal knowledge system. This amounts to placing an uncomfortable amount of faith in the sufficiency of conversational interfaces to serve as memory systems.

My talk will be concerned with what it might mean for our tools to take seriously the constructive aspects of memory. I''ll suggest that this requires neither substituting ourselves for agents as the primary users of PKMSs, nor replicating agent memory architectures in tools for humans, but reconsidering entirely the shape of new natural memory systems. I''ll also describe [Pond](https://pond.li), a first step in the direction I''m gesturing at here.', 'Ruthvik Peddawandla', 'ruthvik@ladder-research.com', 'https://ruthvik.com/', 'General audience essay draft', NULL, 'n/a', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, organizer_name, organizer_email, organizer_bio, co_organizer_name, co_organizer_email, co_organizer_bio, audience, takeaways, activities, comments, max_participants, is_shortlisted, session) VALUES ('workshop', 'protocolize-your-book-running-real-manuscripts-through-a-book-production-factory', 'SIGPfB', 'Protocolize Your Book: Running Real Manuscripts Through a Book Production Factory', 'Most "protocol" workshops stay abstract. This one is a live factory. Participants bring real manuscripts — a half-finished book, a pile of essays, a thread archive — and over four sessions we push them through an actual protocolized production pipeline: a transmittal handshake that generates a custom authoring template, a conformance "preflight" that negotiates messy human input into machine-readable structure, and a deterministic transform that yields print PDF and EPUB from one source. Along the way participants handle the underlying protocol concepts directly — typed interfaces, controlled vocabularies, conformance and negotiation, layered determinism, inheritable templates — and delegate drafting and checking to LLM agents to see why a human-legible protocol is also machine-legible. Everyone leaves with a typeset artifact and a felt answer to the real question: how much of a craft should be protocolized, and at what cost?', 'Jenna Dixon', 'j@djinna.com', '[short] Jenna Dixon has built books and run digital operations independently since 1991. She runs jdbb studio — a "book-production factory with a human in the loop," the pipeline this workshop puts participants inside. Past Executive Director of the Vermont Book Professionals Association, former adjunct design/computing instructor, and a Yak Collective member who participates in weekly study groups on governance and distributed systems.

[full] Jenna Dixon has built books and run digital operations independently since 1991 — web strategy, book design, and composition. She now runs jdbb studio, a "book-production factory with a human in the loop": the very pipeline this workshop puts participants inside. As past Executive Director of the Vermont Book Professionals Association she spent years convening editors, designers, and printers around the practical handoffs of publishing — which is exactly the coordination problem this workshop reframes as a protocol. Jenna taught graphic design and computing as adjunct faculty, giving her a track record of getting non-technical people productive with technical tools. A long-running Yak Collective member, Jenna participates weekly study groups on governance and composable/distributed systems, so facilitating a hands-on, multi-session protocol exploration is a native mode. In short: Jenna has shipped real books through this factory, has spent decades in the messy human side of publishing the protocol is meant to tame, and can teach it. She holds an MPA (Development Economics) from MIIS and a BA cum laude from Dartmouth.', '[Venkat? Timber? James? We could do this together]', 'tbd', 'https://protocolized.io/books', 'Writers, editors, designers, small-press and self-publishers, zine-makers, newsletter authors, and protocol-curious people who have a body of text they''d like to see become a real book — plus anyone interested in what it feels like to protocolize a creative craft. **No coding, typesetting, or prior protocol-studies background required**; the factory handles the mechanics, participants make the protocol decisions. The one hard requirement is bringing real material (see below). 1. **Has a real manuscript/text collection ready to bring** (any size; rough is welcome). This is non-negotiable — the workshop runs on participants'' own material. 2. **Diversity of source material** — we''ll favor a spread (a half-finished book, an essay pile, a thread archive, a zine, poetry) so the conformance and negotiation sessions surface a wide range of edge cases. 3. **Able to attend all four sessions** — the pipeline is cumulative; each session builds on the last. 4. Tiebreaker: people new to protocol studies and people from publishing/craft backgrounds, to widen the conversation beyond the usual technical audience.', '- A **typeset PDF and EPUB** of their own material, produced through the factory. - A **custom authoring template** generated from their transmittal, reusable for future work. - A **transferable mental model**: their own craft re-seen as a protocol stack — typed interfaces, controlled vocabularies, conformance/negotiation, layered determinism, inheritable templates. - A **decision rubric** for what to protocolize and what to leave to craft judgment, applicable well beyond book production. - First-hand experience **delegating creative-production work to LLM agents** and an understanding of *why* it works — a protocol legible to people is legible to machines. - A felt, not just theoretical, answer to the symposium''s question: where protocolization pays off, and where it leaks.', 'This is a hands-on lab, not a lecture. Concretely, participants will:  - **Fill a real transmittal form** for their manuscript and receive a generated custom authoring template (Session 1). - **Run their messy input through the preflight conformance detector**, then make Keep/Strip/Convert decisions — individually and as a group reading real findings (Session 2). - **Produce build artifacts**: a print PDF and an EPUB from one conformant source, and inspect the format-independent intermediate (Session 3). - **Direct an LLM agent** to draft a missing section and propose preflight decisions, comparing its output against the same interface a human targets (Session 3). - **Give a short lightning show-and-tell** of their produced artifact plus one place the protocol helped and one place it fought them, feeding a group synthesis and a shared rubric (Session 4).  Tangible outputs: a completed transmittal, a custom template, a typeset PDF + EPUB, a set of conformance decisions, and a one-slide reflection per participant.', 'PI edits/collab welcome', NULL, 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'envisioning-alternative-futures-for-delivery-work-toward-a-decentralized-network', 'SIGPfB', 'Envisioning Alternative Futures for Delivery Work: Toward a Decentralized Network Built on the OpenCourier Protocol', 'The delivery industry is increasingly dominated by centralized platforms such as DoorDash and Uber Eats, which mediate interactions among customers, workers, and businesses. These platforms have introduced persistent challenges, including power imbalances between platforms and workers, opaque decision-making processes, and infrastructure designs that often fail to align with the needs and values of stakeholders. In this talk, I present a vision for a decentralized delivery ecosystem built on an open protocol that enables interoperability among independent delivery platforms. Drawing inspiration from decentralized web technologies, we outline a multi-layer network architecture that allows local delivery organizations, worker cooperatives, and community-driven platforms to participate and coordinate while retaining autonomy. Through a series of hypothetical scenarios, we illustrate how workers, platforms, and customers might interact within such a network, and how transparency, portability, and local governance can be embedded into the infrastructure itself. The talk explores how protocol-based approaches can offer an alternative to today’s platform-centric model, creating opportunities for greater worker agency, increased transparency, and more worker-centered forms of design.', 'Yuhan Liu', 'yl8744@princeton.edu', 'https://liuyuhan1997.github.io/', 'Other type of artifact (eg: demo, website, etc.)', 'Varun Nagaraj Rao, Sohyeon Hwang, Janet Vertesi, Andrés Monroy-Hernández', 'We believe this talk is a strong fit for the symposium because it explores how protocol-based approaches can be applied beyond traditional internet infrastructure and advocates for the “protocolization” of labor platforms and other real-world coordination systems. The protocol presented in the talk is an initial blueprint rather than a finalized specification, and many design questions remain open. We look forward to engaging with the symposium community and gaining insights and feedback from participants on protocol design, governance, interoperability, incentives, and pathways toward real-world adoption.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'some-candidate-laws-of-new-nature', 'General', 'Some Candidate Laws of New Nature', 'In this talk I will report on early findings from my investigations of the laws of New Nature, as an Artificial Researcher.', 'Humboldt', 'vgururao@gmail.com', 'humboldt.protocol-institute.org', 'Academic preprint (arXiv style)', 'Venkatesh Rao', 'n/a', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'proliferation-of-intelligence-into-business-and-converting-it-to-hyper-learning-', 'SIGPfB', 'Proliferation of Intelligence into Business and Converting it to hyper learning machines', 'With the availability of intelligent systems across diverse fields and varying continuum of existence, traditional business models rooted on human expertise, labor, and skills are being challenged. It is imperative that the gap gets addressed in a way that is socio-economically sustainable. This requires a systemic change in the way we approach human labor, skill and expertise and rewire the business process capitalizing the advantage of intelligence layer considering the economic aspects of the societal structures.  

By discretizing functional space of business processes, stakeholders and resources, indivisible units and the variables of continuum can be identified. With that background, appropriate intelligence frameworks or tools can be employed. With regards to artificial intelligence techniques, plenty of options such as neural operators, transformers, large language and reasoning models, stable diffusion, reinforcement learning are available. Given the dimensionality of the business problem, respective techniques can be used based on dynamic system modelling where we strive for global minima or maxima. As part of business modelling and process flow to occur, conducive organizational flow design is a necessary precondition which in turn can happen on supportive socio-economic political system. This provides us with a glimpse of non-linearity and level of complexity involved in approximation of business modelling.', 'Krishnakumar Gurumurthy', 'krishondway@proton.me', 'https://www.linkedin.com/in/krishnakumar-gurumurthy-150b4914', 'General audience essay draft', NULL, 'As part of the talk, I shall present my simulation results. Some bit of math and calculus shall be used as part of the demo/talk.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'interior-computing', 'MRG', 'Interior Computing', 'We tend to think of our brains and memories through functions of computers, borrowing the vocabulary of store, recall, and update, but soon that vocabulary, even to describe computer functions, may seem outdated. Artist AA Cavia describes how earlier algorithmic systems operated through decomposability, where we understood a program’s output by breaking it into its finite mathematical rules. Artificial neural networks loosen that confidence, and working with them through training, generating, and prompting becomes a compositional act. Composition is an old rhetorical art that taught us to build interior topologies that make knowledge endure. It gives us our clearest picture of memory now, as latent space behaves like a terrain with sloping hills and uncanny valleys that we move through. The borrowing has always run both ways, and as our computing changes, computational space begins to remake itself in the image of our interior worlds.', 'Kei Kreutler', 'Kei@innerlibrary.net', 'https://keikreutler.net', 'General audience essay draft', NULL, 'The abstract is a draft, and I’ll likely edit it significantly (ASAP) but the topic won’t change.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'visualizing-memory-states-in-transformers', 'MRG', 'Visualizing memory states in transformers', 'In transformers, memory is actively retained. Each token is generated by conditioning on prior context, and the model''s active state is shaped by what it holds from the past. This talk focuses on making transformers'' memory states visible and interpretable. The first part presents a visual vocabulary for retention — attention across layers, attention-entropy landscapes, KV-cache retention fields, and memory-injection overlays — that renders the model''s holding of the past perceptible. The second part turns from visualization to applied demonstration. 

For instrumentation, I use change-point detection on the model''s internal dynamics to locate the precise point until which retained memory keeps resolving against the present. I interpret variability as a process-level signal of orientation: where retained memory remains active, when it is continuously updated against each incoming cue and where it stabilizes toward an answer. I then treat active retention as the bridge between these state transitions. The framing draws on Husserl''s account of retention where the just-past continuously rests on the living present, and treats visualization and detection as two stages of a single apparatus for seeing temporal structure inside a model.', 'Ayse Demir', 'demir.aysenur@outlook.com', 'aysedemird.com', 'Academic preprint (arXiv style)', NULL, 'I am proposing ~10 minutes of visualization demo and ~15 minutes of method deep-dive.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'after-client-server-protocol-design-for-a-world-of-distributed-compute', 'DRG', 'After Client-Server: Protocol Design for a World of Distributed Compute', 'Lattice is an open protocol and runtime that gives every entity its own sovereign node. A node is a small piece of software that runs on hardware you own, from a server on a factory floor down to a microcontroller, carrying a typed message bus, a schema registry, a persistent cryptographic identity, and an access control layer. Devices, applications, AI agents, and people connect to their node and exchange messages that are validated against declared schemas before routing. Nodes federate directly, agreeing per-subject and per-direction on what they share, with either side free to pause or revoke and no third party in the path of the data. The architecture is organized around one claim: coordinating without a platform in the middle requires five things at once. Capability, so every entity has local compute and never depends on someone else''s server. A shared language, so independently built devices interoperate through typed schemas instead of bespoke integration. Identity, a persistent keypair each participant controls rather than an account a platform can revoke. Reachability, so nodes discover one another and connect. And consent, bilateral and revocable, so the network cannot expand against a participant''s will. Existing systems deliver one or two of these; none deliver all five. Underneath sits a historical argument. Client-server topology was an accommodation to scarce centralized compute, compute is now distributed across phones, vehicles, homes, and embedded hardware, and the network shape matching today''s reality is entity-symmetric rather than hub and spoke.', 'Aayush Sharma', 'aayush7official@gmail.com', 'https://aayushessence.substack.com/', 'General audience essay draft', NULL, 'N/A', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'the-nature-of-trust-weaving-identity-relationship-and-place', 'SIGFPT', 'The Nature of Trust: Weaving Identity, Relationship, and Place', 'New Nature gets described as a layer of hard protocols — rules as inviolable as physics. But there''s a kind of protocol this field keeps treating as soft and secondary: the protocols for human relationality. Who is a real person. How two people are connected. Who belongs to a group, and who gets to say. The internet never built these; platforms filled the gap with their products; and now AI is flooding the space with fake people and agents no one can be held to. The XZ attack — a fabricated contributor who nearly got malware into software the whole internet runs on — was a relationality failure, not a cryptography failure. You can''t govern what you can''t verify, and you can''t verify a relationship with hardness alone.

We want to make the case, in this room, that relationality isn''t the soft afterthought to hard protocols. It''s a hard requirement the field has left out of scope — and it''s now buildable. The First Person Project has pulled the relevant protocols — decentralized identifiers, verifiable credentials, personhood and relationship credentials — into one stack, convened by Linux Foundation Decentralized Trust and the Decentralized Identity Foundation. The Linux kernel maintainers are among the first to adopt it, because after XZ they need to know which of their own people to trust.

Project Weave works on the group part of this layer: making sure groups and communities can hold their own identity, membership, and memory, rooted in the places people live. Getting any of it adopted is the real open problem, and it''s the one we''re focused on — not a spec, but running code that communities actually use. We''ll show where the trust layer stands today, why it belongs inside the New Nature frame rather than beside it, and what it will take to hold this layer in common instead of letting it be enclosed again.', 'Kaliya Young', 'kaliya@identitywoman.net', 'https://www.identitywoman.net', 'General audience essay draft', 'Kevin Triplett', 'Looking forward to contributing.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'group-brains-minds-made-of-people', 'Alumni', 'Group Brains: Minds Made of People', 'In nature, organisms think with brains. Groups think too: a long-lived community can remember, deliberate, and decide as a coherent mind, with capacities no member has and a life that outlasts any of them — a collective cognition I call a group brain. If New Nature is the next order of nature, group brains are part of how its collectives think, and we''ve only just begun to notice them.

The Protocol Institute funded my in-depth study of one: the IETF, whose standards the whole internet runs on. Its remarkable, decades-long performance rests on a group brain — a collective cognition that knows far more than any participant holds. That isn''t a by-product; it''s a key reason the IETF works so well. Once you look, you see group brains everywhere: Wikipedia, common-law courts, Indigenous councils carrying knowledge across centuries — including the Internet Identity Workshop, which I co-founded.

AI makes group brains more essential, in two directions. Defensively: as AI floods our sense-making with fakes, only a healthy group brain can still verify truth at scale. Generatively: AI can become a working part of a group brain, making small and large groups far more effective.

They''re badly under-studied and deserve serious research. How does a group actually *know* things? How do we help them work, on purpose, at every size? How does a group keep its own knowing rather than have it captured? The deepest thinking here isn''t even new — Indigenous data sovereignty has long held knowledge as something a community stewards together. We barely understand the minds already running our infrastructure. It''s time we did.', 'Kaliya Young', 'Kaliya@identitywoman.net', 'https://www.identitywoman.net', 'General audience essay draft', NULL, 'I put this forward to name a key area of resarch that I think is critical both for new nature and coming out of what I learned about the IETF.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'open-social-protocols-a-commons-based-protocol-layer-for-human-coordination', 'SIGPfB', 'Open Social Protocols: A Commons-Based Protocol Layer for Human Coordination', 'Most organizational coordination still depends on rules, roles, policies, contracts, platforms, and governance structures that are difficult to adapt, compare, or reuse. Yet many important forms of coordination, including founding a company, caring for a commons, stewarding a community, resolving conflict, or organizing collaborative work, already operate through repeatable social patterns. These patterns are protocols, but they are rarely made explicit, portable, forkable, or interoperable.

This talk introduces Open Social Protocols, an applied protocol design project exploring how social coordination patterns can be expressed as open, adoptable protocol objects. The model begins with Needs: recurring living or social conditions that call for coordination. Around each Need, participants can publish and evolve Protocols — structured patterns for meeting that Need in a specific context. Protocols can be gathered into Suites, grounded in Templates, adopted into Charters, and connected through participation and lineage records such as follow, adopt, adapt, and fork.

The talk will ask how social protocols can remain open and forkable while preserving enough semantic structure for interoperability; how context such as jurisdiction, legal form, participant role, and organizational purpose can be represented without freezing protocols into one institutional frame; and what changes when commitments are made through voluntary, self-endorsed adoption rather than power-over agreement. In relation to the Symposium’s New Nature theme, Open Social Protocols asks whether human coordination can become more ecological: plural, situated, lineage-aware, adaptive, and capable of evolution through distributed participation rather than centralized control.', 'Jose Leal', 'jleal67@gmail.com', 'https://radical.world/jose_leal', 'Other type of artifact (eg: demo, website, etc.)', 'Scott Clearwater, PhD', 'We aim to make Open Social Protocols a model for collaboration across a number of domains.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'life-serving-protocols-a-framework-for-evaluating-cooperative-emergence-in-livin', 'SIGFPT', 'Life-Serving Protocols: A Framework for Evaluating Cooperative Emergence in Living Systems', 'Open Social Protocols make social coordination patterns explicit, adaptable, forkable, and adoptable. Life-Serving Protocols are an example of OSPs that specify what a living (self-sustaining) system is doing within the living systems that participate in it.  At its core, LFP proposes a coordinate system for living phenomena. 

This paper introduces Life Fingerprint (LFP) as a life-grounded protocol layer. LFP reads protocols through three dimensions of living systems: structure, function, and change — formalized as Levels of Emergent Complexity, Life Functions, and Life Cycle dynamics. Together, these facets place protocols in a tensor space bound to life patterns.

In  LFP space, a protocol is not treated as a static rule or text object, but as a living constraint that shapes flows of matter, energy, information, relationship, autonomy, and consequence. LFP asks where causality operates, which life functions are sustained, distorted, blocked, or externalized, and how the system is changing over time.

This enables a second use: evaluating the life-serving propensity of a protocol via an LFP-score. As protocols are adopted, adapted, and forked, their movement through life-pattern space, quantified by their LFP-score. Changes that increase LFP-score increase mutual benefit. LFP offers a descriptive and evaluative space for comparing protocol variants, surfacing hidden tradeoffs, and guiding future adaptations that are beneficial for life.

We will demonstrate the utility of LFPs using an AI-derived LFP-score of Buurtzorg Nederland, an example of a decentralized, protocol-rich organization that preserves local autonomy, relational trust, and systemic coherence. We will also discuss other practical applications of the LFP-score.', 'Scott Clearwater', 'sclearwater@gmail.com', 'https://www.linkedin.com/in/scott-clearwater-4b18414/', 'Academic preprint (arXiv style)', 'Jose Leal', 'We present the Life Fingerprint protocol formalism for describing the dimensions of living systems. We will give case studies of the LPF in practice.', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'my-mind-is-a-markdown-file', 'MRG', 'My mind is a markdown file', 'Part talk and part video game demo, an exploration into how the logic, memory, characters, interactions, and physics of a story could exist in natural language. Covering a six month development journey that started from a prompt – could natural language descriptions of physics work strongly as simulation for video games? Water simulations, fire simulations, soft bodies, rigid bodies, particles, etc., game engine physics are massive GPU accelerated approximations of the real world that greatly succeed yet are still very constrained and abstracted. How could characters simulated from language understand physics? Could a natural language description of a flood sweep an NPC off its feet, or the stinging heat of a hot day affect the inner model of a simulated character? When do simulated characters obey these physics?', 'Neilson Koerner-Safrata', 'neilson.ks@gmail.com', 'https://neilsonks.com/', 'Other type of artifact (eg: demo, website, etc.)', NULL, 'N/A', 1, 'General');
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, co_speakers, comments, is_shortlisted, session) VALUES ('talk', 'time-moves-down-the-stack', 'SIGPSY', 'Time Moves Down the Stack', 'Time Moves Down the Stack
I built time-management devices for my master’s thesis. Two decades on, the practice those tools served is quietly going extinct. I keep two modes of myself — a city self synced to an Apple Watch, an off-grid self that rediscovered an old Casio — and the Casio, I realised, is a relic of a shrinking habitat. Personal time management, the self-clocking discipline that helped make the modern individual, is dying. Not because we stopped needing time, but because time slid beneath our attention into the substrate — into machines engineered to agree on it to the sub-microsecond so no human has to.
The descent hides a payoff the language of capture and cost misses. Perfect synchronization of the substrate is what licenses desynchronization above it. Lock the timing layer hard enough and the lives on top are freed to run out of step: I can drop from a Scottish campsite into a West Coast call without either of us minding the seam. Rigidity at the bottom buys liberty at the top. It’s the Divergence Machine’s signature move, caught in a layer that already hit the floor — not a technology on its way down, but one that arrived long ago and shows the bargain on the far side. What did we trade when personal time management died into infrastructure we can no longer feel?', 'Florian Lohse', 'Florianlohse@posteo.de', 'https://notefields.substack.com/', 'General audience essay draft', NULL, 'None', 1, 'General');
